          "correctKey": "Б",
          "answerText": "У наочній моделі підручника оточення молекули біля межі рідина—газ несиметричне: з боку рідини сусідів більше, ніж із боку газу. Перенесення молекули з об’єму в поверхневий шар потребує роботи, тому поверхневий шар має надлишкову енергію. Ця модель пояснює енергетичну ціну поверхні; її не слід сприймати як твердження про необмежене прискорення кожної поверхневої молекули вглиб.",
